DELIVERY_NOTE.mono:
:root{--ink:#000;--mute:#000;--line:#000;--soft:#fff;--red:#000;--gold:#000;--bg:#e9ebf0}
*{box-sizing:border-box;margin:0;padding:0}
html{-webkit-print-color-adjust:exact;print-color-adjust:exact}
body{background:var(--bg);font:13px/1.45 "Be Vietnam Pro","Segoe UI",Roboto,Arial,sans-serif;color:var(--ink);padding:20px}
.page{width:210mm;min-height:297mm;margin:0 auto;background:#fff;padding:12mm 12mm 10mm;position:relative;box-shadow:0 2px 14px rgba(0,0,0,.15);border-top:0}
.head{display:flex;gap:14px;align-items:flex-start;padding-bottom:10px;border-bottom:2px solid var(--ink)}
.logo{flex:none;width:92px}
.co{flex:1;font-size:11.5px;color:var(--mute)}
.co h1{font-size:20px;color:var(--ink);letter-spacing:.2px;line-height:1.2;margin-bottom:3px}
.co b{color:var(--ink);font-weight:600}
.co p+p{margin-top:1px}
.qr{flex:none;width:92px;text-align:center;font-size:9.5px;color:var(--mute)}
.qr .box{width:92px;height:92px;border:1px solid #000;display:flex;align-items:center;justify-content:center;margin-bottom:2px}
.qr img{width:100%;height:100%;object-fit:contain}
.titlebar{display:flex;justify-content:space-between;align-items:flex-end;margin:14px 0 10px;gap:12px}
.titlebar h2{font-size:21px;line-height:1.2;font-weight:700;padding-left:10px;border-left:5px solid var(--red)}
.meta{text-align:right;font-size:12.5px}
.meta div span{color:var(--mute)}
.meta b{font-weight:600}
.cust{border:1px solid #000;display:grid;grid-template-columns:1fr auto;gap:2px 28px;background:var(--soft);border-radius:6px;padding:8px 12px;margin-bottom:12px;font-size:12.5px}
.cust .full{grid-column:1/-1}
.cust span{color:var(--mute)}
.cust b{font-weight:600}
table{width:100%;border-collapse:collapse;font-size:12px}
th{background:#fff;color:#000;border-bottom:2px solid #000;font-weight:600;padding:6px 7px;text-align:center;border:1px solid var(--ink)}
td{padding:6px 7px;border:1px solid #000;vertical-align:top}
tr{break-inside:avoid}
.c{text-align:center}.r{text-align:right;font-variant-numeric:tabular-nums}
.pn{display:flex;justify-content:space-between;gap:8px}
.pn b{font-weight:600}
.tag{font-weight:600;color:var(--red);white-space:nowrap}
.cut{display:flex;justify-content:space-between;color:var(--mute);font-size:11.5px;margin-top:2px;color:#000}
.cut ul{list-style:none}
.cut .rt{text-align:right;white-space:nowrap}
.note{font-size:11px;font-style:italic}
tr.sum td{background:#fff;border-top:2px solid #000;font-weight:700;font-size:12.5px}
.tot{margin:12px 0 4px auto;width:290px;font-size:12.5px}
.tot div{display:flex;justify-content:space-between;padding:3px 0}
.tot span{color:var(--mute)}
.tot .big{border-top:2px solid var(--ink);margin-top:4px;padding-top:6px;font-size:15px;font-weight:700;color:var(--red)}
.tot .big span{color:var(--red)}
.tot b{font-variant-numeric:tabular-nums;font-weight:600}
.words{text-align:right;font-style:italic;font-weight:600;margin-bottom:18px}
.sign{display:flex;justify-content:space-around;text-align:center;margin-top:8px;gap:8px}
.sign div{flex:1;min-height:92px}
.sign b{display:block;font-weight:600}
.sign small{display:block;color:var(--mute);font-size:10.5px}
.sign em{display:block;margin-top:46px;font-style:normal;font-weight:600}
.terms{margin-top:16px;padding-top:8px;border-top:1px solid var(--line);font-size:11px;color:var(--mute)}
.terms b{color:var(--ink)}
.foot{margin-top:14px;display:flex;justify-content:space-between;font-size:10px;color:var(--mute)}
@page{size:A4;margin:0}
@media print{body{background:#fff;padding:0}.page{box-shadow:none;margin:0}}

